<?php

namespace App\Models;

use App\Enums\Adaptive\AttemptStatus;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/** A learner's attempt at an assessment (spec §6.1). `active_key` is generated by the database. */
class Attempt extends Model
{
    protected $attributes = ['status' => 'in_progress'];

    protected $fillable = [
        'learner_id', 'assessment_id', 'attempt_number', 'status',
        'started_at', 'submitted_at', 'finalised_at', 'voided_by', 'voided_reason',
    ];

    protected function casts(): array
    {
        return [
            'status' => AttemptStatus::class,
            'started_at' => 'datetime',
            'submitted_at' => 'datetime',
            'finalised_at' => 'datetime',
        ];
    }

    public function assessment(): BelongsTo
    {
        return $this->belongsTo(Assessment::class);
    }

    public function learner(): BelongsTo
    {
        return $this->belongsTo(User::class, 'learner_id');
    }

    public function items(): HasMany
    {
        return $this->hasMany(AttemptItem::class)->orderBy('position');
    }

    public function answers(): HasMany
    {
        return $this->hasMany(Answer::class);
    }
}
